[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "paint-calculator-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "paint-calculator-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium",
            "children": [
              {
                "id": "summary_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "summary_col",
                    "type": "Column",
                    "properties": {
                      "spacing": "small",
                      "children": [
                        {
                          "id": "summary_text",
                          "type": "Text",
                          "properties": {
                            "text": "To paint your room's four walls with two coats, you will need to purchase:"
                          }
                        },
                        {
                          "id": "summary_heading",
                          "type": "Heading",
                          "properties": {
                            "text": "3 Gallons of Paint",
                            "level": 2,
                            "horizontalAlignment": "center"
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "details_tabs",
                "type": "Tabs",
                "properties": {
                  "tabs": [
                    {
                      "id": "tab_detailed",
                      "type": "Tab",
                      "properties": {
                        "header": "Detailed Calculation",
                        "child": {
                          "id": "detailed_list",
                          "type": "List",
                          "properties": {
                            "children": [
                              {
                                "id": "detail_step_1",
                                "type": "ListItem",
                                "properties": {
                                  "title": "1. Calculate Perimeter",
                                  "subtitle": "(14 feet + 12 feet) * 2 = 52 feet"
                                }
                              },
                              {
                                "id": "detail_step_2",
                                "type": "ListItem",
                                "properties": {
                                  "title": "2. Calculate Wall Area",
                                  "subtitle": "52 feet (perimeter) * 8 feet (height) = 416 square feet"
                                }
                              },
                              {
                                "id": "detail_step_3",
                                "type": "ListItem",
                                "properties": {
                                  "title": "3. Calculate Total Area (2 Coats)",
                                  "subtitle": "416 square feet * 2 coats = 832 square feet"
                                }
                              },
                              {
                                "id": "detail_step_4",
                                "type": "ListItem",
                                "properties": {
                                  "title": "4. Calculate Gallons Needed",
                                  "subtitle": "832 square feet / 350 square feet per gallon = 2.377 gallons"
                                }
                              },
                              {
                                "id": "detail_step_5",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Gallons to Purchase",
                                  "subtitle": "Since paint is sold in whole gallons, round up to 3 gallons."
                                }
                              }
                            ]
                          }
                        }
                      }
                    },
                    {
                      "id": "tab_breakdown",
                      "type": "Tab",
                      "properties": {
                        "header": "Calculation Breakdown",
                        "child": {
                          "id": "breakdown_list",
                          "type": "List",
                          "properties": {
                            "children": [
                              {
                                "id": "item_length",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Room Length",
                                  "trailing": {
                                    "id": "val_length",
                                    "type": "Text",
                                    "properties": {
                                      "text": "14 feet"
                                    }
                                  }
                                }
                              },
                              {
                                "id": "item_width",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Room Width",
                                  "trailing": {
                                    "id": "val_width",
                                    "type": "Text",
                                    "properties": {
                                      "text": "12 feet"
                                    }
                                  }
                                }
                              },
                              {
                                "id": "item_height",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Ceiling Height",
                                  "trailing": {
                                    "id": "val_height",
                                    "type": "Text",
                                    "properties": {
                                      "text": "8 feet"
                                    }
                                  }
                                }
                              },
                              {
                                "id": "item_coverage",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Paint Coverage",
                                  "trailing": {
                                    "id": "val_coverage",
                                    "type": "Text",
                                    "properties": {
                                      "text": "350 sq ft/gallon"
                                    }
                                  }
                                }
                              },
                              {
                                "id": "item_coats",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Number of Coats",
                                  "trailing": {
                                    "id": "val_coats",
                                    "type": "Text",
                                    "properties": {
                                      "text": "2"
                                    }
                                  }
                                }
                              },
                              {
                                "id": "item_divider_1",
                                "type": "Divider"
                              },
                              {
                                "id": "item_perimeter",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Perimeter",
                                  "trailing": {
                                    "id": "val_perimeter",
                                    "type": "Text",
                                    "properties": {
                                      "text": "52 feet"
                                    }
                                  }
                                }
                              },
                              {
                                "id": "item_wall_area",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Wall Area",
                                  "trailing": {
                                    "id": "val_wall_area",
                                    "type": "Text",
                                    "properties": {
                                      "text": "416 sq ft"
                                    }
                                  }
                                }
                              },
                              {
                                "id": "item_total_area",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Total Area to Paint",
                                  "trailing": {
                                    "id": "val_total_area",
                                    "type": "Text",
                                    "properties": {
                                      "text": "832 sq ft"
                                    }
                                  }
                                }
                              },
                              {
                                "id": "item_gallons_needed",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Gallons Needed",
                                  "trailing": {
                                    "id": "val_gallons_needed",
                                    "type": "Text",
                                    "properties": {
                                      "text": "2.38 gallons (approx)"
                                    }
                                  }
                                }
                              },
                              {
                                "id": "item_divider_2",
                                "type": "Divider"
                              },
                              {
                                "id": "item_gallons_buy",
                                "type": "ListItem",
                                "properties": {
                                  "title": "Gallons to Buy",
                                  "trailing": {
                                    "id": "val_gallons_buy",
                                    "type": "Text",
                                    "properties": {
                                      "text": "3 gallons",
                                      "weight": "bold"
                                    }
                                  }
                                }
                              }
                            ]
                          }
                        }
                      }
                    }
                  ]
                }
              },
              {
                "id": "actions_row",
                "type": "Row",
                "properties": {
                  "spacing": "medium",
                  "mainAxisAlignment": "center",
                  "children": [
                    {
                      "id": "shop_button",
                      "type": "Button",
                      "properties": {
                        "label": "Shop for Paint",
                        "style": "primary",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "args": {
                            "url": "https://example.com/shop-paint"
                          }
                        }
                      }
                    },
                    {
                      "id": "tips_button",
                      "type": "Button",
                      "properties": {
                        "label": "Painting Tips",
                        "style": "secondary",
                        "action": {
                          "type": "functionCall",
                          "call": "openUrl",
                          "args": {
                            "url": "https://example.com/painting-tips"
                          }
                        }
                      }
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    }
  }
]
